import React, { useState } from 'react';

const AccountSettings = () => {
  const [settings, setSettings] = useState({
    notifications: true,
    darkMode: true,
    emailUpdates: true,
    twoFactor: false,
  });

  const handleSettingChange = (key) => {
    setSettings(prev => ({
      ...prev,
      [key]: !prev[key]
    }));
  };

  return (
    <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-2xl p-6 shadow-lg border border-white/30 dark:border-neutral-800/50">
      <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-6">Compte</h3>
      <div className="space-y-4">
        <SettingItem
          title="Notifications"
          description="Recevoir des notifications par email"
          enabled={settings.notifications}
          onChange={() => handleSettingChange('notifications')}
        />
        <SettingItem
          title="Mode sombre"
          description="Activer le thème sombre"
          enabled={settings.darkMode}
          onChange={() => handleSettingChange('darkMode')}
        />
        <SettingItem
          title="Authentification à deux facteurs"
          description="Ajouter une couche de sécurité supplémentaire"
          enabled={settings.twoFactor}
          onChange={() => handleSettingChange('twoFactor')}
        />
      </div>
    </div>
  );
};

const SettingItem = ({ title, description, enabled, onChange }) => (
  <div className="flex items-center justify-between p-4 rounded-xl bg-neutral-50 dark:bg-neutral-800/30">
    <div>
      <p className="font-medium text-neutral-900 dark:text-white">{title}</p>
      <p className="text-sm text-neutral-600 dark:text-neutral-400">{description}</p>
    </div>
    <button
      onClick={onChange}
      className={`relative inline-flex h-6 w-11 items-center rounded-full ${enabled ? 'bg-primary-500' : 'bg-neutral-300 dark:bg-neutral-700'}`}
    >
      <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition ${enabled ? 'translate-x-6' : 'translate-x-1'}`} />
    </button>
  </div>
);

export default AccountSettings;
